namespace Shop;

public enum CustomerType { Regular, Loyal, Student, Partner }

public record OrderLine(string Sku, decimal UnitPrice, int Quantity);

public record Order(CustomerType Customer, IReadOnlyList<OrderLine> Lines);

// A customer's discount rule: how much comes off a subtotal, and how it reads on the receipt.
public record Discount(string Description, Func<decimal, decimal> Amount);

public static class Discounts
{
    // To add a customer type: add the enum value and one entry here.
    private static readonly Dictionary<CustomerType, Discount> ByCustomer = new()
    {
        [CustomerType.Regular] = new("Regular: no discount", _ => 0m),
        [CustomerType.Loyal] = new("Loyal: 5% off", subtotal => subtotal * 0.05m),
        [CustomerType.Student] = new("Student: 10% off, max 30", subtotal => Math.Min(subtotal * 0.10m, 30m)),
        [CustomerType.Partner] = new("Partner: 10% off, 15% off above 1,000",
            subtotal => subtotal * (subtotal > 1000m ? 0.15m : 0.10m)),
    };

    public static Discount For(CustomerType customer) =>
        ByCustomer.TryGetValue(customer, out var discount)
            ? discount
            : throw new InvalidOperationException($"No discount rule defined for customer type {customer}.");
}

public static class PriceCalculator
{
    public static decimal Subtotal(Order order) => order.Lines.Sum(l => l.UnitPrice * l.Quantity);

    public static decimal Total(Order order)
    {
        var subtotal = Subtotal(order);
        return subtotal - Discounts.For(order.Customer).Amount(subtotal);
    }

    // The single receipt line describing the customer's discount.
    public static string DiscountLine(Order order) => Discounts.For(order.Customer).Description;
}

