using Shop;

public class PriceCalculatorTests
{
    private static Order OrderOf(CustomerType customer) =>
        new(customer, [new OrderLine("A", 100m, 2), new OrderLine("B", 50m, 1)]);

    private static Order OrderWithSubtotal(CustomerType customer, decimal subtotal) =>
        new(customer, [new OrderLine("A", subtotal, 1)]);

    [Fact]
    public void Regular_customer_pays_the_subtotal() =>
        Assert.Equal(250m, PriceCalculator.Total(OrderOf(CustomerType.Regular)));

    [Fact]
    public void Loyal_customer_gets_five_percent_off() =>
        Assert.Equal(237.50m, PriceCalculator.Total(OrderOf(CustomerType.Loyal)));

    [Fact]
    public void Student_gets_ten_percent_off_below_the_cap() =>
        Assert.Equal(225m, PriceCalculator.Total(OrderOf(CustomerType.Student)));

    [Theory]
    [InlineData(300, 270)]    // exactly at the cap: 10% = 30
    [InlineData(1000, 970)]   // 10% would be 100, capped at 30
    public void Student_discount_never_exceeds_thirty(decimal subtotal, decimal expected) =>
        Assert.Equal(expected, PriceCalculator.Total(OrderWithSubtotal(CustomerType.Student, subtotal)));

    [Theory]
    [InlineData(250, 225)]       // 10%
    [InlineData(1000, 900)]      // up to and including 1,000: 10%
    [InlineData(1000.01, 850.0085)] // above 1,000: 15% of the whole order
    [InlineData(2000, 1700)]
    public void Partner_gets_ten_percent_up_to_1000_and_fifteen_above(decimal subtotal, decimal expected) =>
        Assert.Equal(expected, PriceCalculator.Total(OrderWithSubtotal(CustomerType.Partner, subtotal)));

    [Theory]
    [InlineData(CustomerType.Regular, "Regular: no discount")]
    [InlineData(CustomerType.Loyal, "Loyal: 5% off")]
    [InlineData(CustomerType.Student, "Student: 10% off, max 30")]
    [InlineData(CustomerType.Partner, "Partner: 10% off, 15% off above 1,000")]
    public void Receipt_shows_one_discount_line_per_customer(CustomerType customer, string expected) =>
        Assert.Equal(expected, PriceCalculator.DiscountLine(OrderOf(customer)));

    [Fact]
    public void Every_customer_type_has_a_discount_rule()
    {
        foreach (var customer in Enum.GetValues<CustomerType>())
            Assert.NotNull(Discounts.For(customer));
    }
}

